"""Keep caches inside the package; an opt-in audit guard supports offline relocation tests."""
from pathlib import Path
import os, sys
root = Path(sys.executable).resolve().parents[2]
cache=root/'work/cache'
cache.mkdir(parents=True,exist_ok=True)
os.environ['MPLCONFIGDIR']=str(cache/'matplotlib')
os.environ['MPLBACKEND']='Agg'
os.environ['JOBLIB_TEMP_FOLDER']=str(cache/'joblib')
os.environ['TEMP']=os.environ['TMP']=str(cache)
sys.dont_write_bytecode=True
if os.environ.get('BDSF_OFFLINE_TEST')=='1':
    def guard(event,args):
        if event in ('socket.connect','socket.connect_ex','socket.getaddrinfo','socket.bind'):
            raise PermissionError('BDSF offline test: network disabled')
        if event=='open':
            try: path=Path(os.fsdecode(args[0])).resolve()
            except (TypeError,ValueError,OSError): return
            if path.drive.upper() in ('D:','S:') and not path.is_relative_to(root):
                raise PermissionError('BDSF isolation: external D:/S: file access blocked')
            if 'codex-runtimes' in str(path).lower() or '.cache/codex' in path.as_posix().lower():
                raise PermissionError('BDSF isolation: author runtime access blocked')
    sys.addaudithook(guard)
